    if packet["schema"] != "REI_FINITE_THERMAL_LITERAL_BINDING_V1" or packet["source_commit"] != SOURCE_PIN or packet["unit"] != UNIT:
        raise ValueError("literal binding schema/source/unit mismatch")
    rows = packet["literal_readback"]
